"""Source check: the UI parses and every file it references exists."""
from pathlib import Path
import json
import re
import subprocess

root = Path(__file__).resolve().parents[1]
app = root / 'app'
for js in ['main.js', 'device.js']:
    subprocess.run(['node', '--check', str(app / js)], check=True)
html = (app / 'index.html').read_text()
for reference in re.findall(r'(?:src|href)=["\']([^"\']+)', html):
    # local-catalog.js is generated by scripts/local-wallpapers.py and is optional.
    if ':' in reference or reference.endswith('local-catalog.js'):
        continue
    assert (app / reference).is_file(), 'Missing bundled resource: ' + reference
for css in app.rglob('*.css'):
    for reference in re.findall(r'url\(["\']?([^)"\']+)', css.read_text()):
        if ':' not in reference:
            assert (css.parent / reference.split('?')[0]).is_file(), 'Missing CSS resource: ' + reference
# Wallpaper files are named at runtime, so check the bundled catalogue explicitly.
for wall in json.loads((app / 'assets/wallpapers/SOURCES.json').read_text()):
    for field in ['src', 'thumb']:
        assert (app / wall[field]).is_file(), 'Missing wallpaper: ' + wall[field]
    for suffix in ['study-soft', 'field-blur', 'field-frost', 'field-clear']:
        assert (app / ('assets/materials/%s-%s.jpg' % (wall['id'], suffix))).is_file(), 'Missing material: %s/%s' % (wall['id'], suffix)
    assert (app / ('assets/wallpapers/%s-panel.jpg' % wall['id'])).is_file(), 'Missing panel backdrop: ' + wall['id']
print('Sources and bundled resources are valid.')
